#define BoxSize iResolution.xy/5.

#define spacing 100.

float geometry(vec2 fc){

	// translating position to center bottom

	vec2 pos = fc - iResolution.xy * vec2(.5,.5);

  // strip which this pos belong to

  vec2 strip = floor((abs(pos)-BoxSize*vec2(.5,1.))/spacing)+1.;

  // current pos octave

  float octave = max(strip.x,strip.y);



  /* 

  	make your magic here

  */



  // tonemapping for viewing

  return octave/(octave+1.);

}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {

	float box = geometry(fragCoord.xy);

	fragColor = vec4(box);

}
